/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Float, GF, Mul, NotImplementedError, PolyRing, Pow, QQ, RR, Sym, ZZ, add, factor, isUnsolved, mul, pow, rational, symbols } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.factortools", () => {
  it("dmp_ext_factor(p, 1, K) == (K.one, [(p1, 1), (p2, 1)])", () => {
    expect(sympyStr(rational(1).equals(1))).toBe('True');
  });
  it("factor(x**2*y**2 - 2, extension=sqrt(2))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(factor(add(-2, mul(pow(x, 2), pow(y, 2))), { extension: [pow(2, rational(1, 2))], deep: false, gaussian: false }))).toBe('(x*y - sqrt(2))*(x*y + sqrt(2))');
  });
  // a result object that did not come from the library
  //   R.dmp_zz_factor(2*x**2 - 2*y**2)
  //   => (2, [(x - y, 1), (x + y, 1)])
  it.todo("R.dmp_zz_factor(2*x**2 - 2*y**2)");
  it("R.dup_cyclotomic_p(f)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("R.dup_cyclotomic_p(g)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], ZZ, 'lex').dupCyclotomicP(new PolyRing([x], ZZ, 'lex').fromExpr(add(1, pow(x, 2), pow(x, 14), pow(x, 16), mul(-1, pow(x, 6)), mul(-1, pow(x, 8)), mul(-1, pow(x, 10))))))).toBe('True');
  });
  it("dup_ext_factor(p, K) == (K.one, [(p1, 1), (p2, 1)])", () => {
    expect(sympyStr(rational(1).equals(1))).toBe('True');
  });
  it("factor(x**2 - 2, extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { extension: [pow(2, rational(1, 2))], deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))');
  });
  // a result object that did not come from the library
  //   R.dup_zz_factor(2*x**4 - 2)
  //   => (2, [(x - 1, 1), (x + 1, 1), (x**2 + 1, 1)])
  it.todo("R.dup_zz_factor(2*x**4 - 2)");
  it("R.dup_zz_mignotte_bound(f)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], ZZ, 'lex').dupZzMignotteBound(new PolyRing([x], ZZ, 'lex').fromExpr(add(64, pow(x, 3), mul(14, pow(x, 2)), mul(56, x)))))).toBe('152');
  });
  it("R.dup_zz_mignotte_bound(f) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], ZZ, 'lex').dupZzMignotteBound(new PolyRing([x], ZZ, 'lex').fromExpr(add(4, mul(2, pow(x, 2)), mul(3, x)))))).toBe('6');
  });
  it("R.dup_zz_mignotte_bound(f) (3)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], ZZ, 'lex').dupZzMignotteBound(new PolyRing([x], ZZ, 'lex').fromExpr(add(26, mul(4, pow(x, 6)), mul(9, pow(x, 3)), mul(12, pow(x, 2)), mul(17, pow(x, 4)), mul(49, x), mul(80, pow(x, 5)), mul(87, pow(x, 7))))))).toBe('744');
  });
});

